prog_src = '''import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "primitives"))
from arc_dsl import *

def nshape(cells_):
    r0 = min(r for r, c in cells_); c0 = min(c for r, c in cells_)
    return frozenset((r - r0, c - c0) for r, c in cells_)

def Lshape_obj(objs):
    for cs_, col, ul, sz in objs:
        rs = [r for r, c in cs_]; cls = [c for r, c in cs_]
        if max(rs) - min(rs) + 1 + max(cls) - min(cls) + 1 - 1 == sz and sz >= 6:
            return (cs_, col, ul, sz)
    return None

def solve(grid):
    objs = objlist(grid)
    L = Lshape_obj(objs)
    nonL = [m for m in objs if m[0] != L[0]]
    classes = {}
    for m in nonL:
        classes.setdefault(nshape(m[0]), []).append(m)
    exact2 = {k: v for k, v in classes.items() if len(v) == 2}
    samecol = [(max(m[3] for m in v), k, v) for k, v in exact2.items() if v[0][1] == v[1][1]]
    if samecol:
        _, k, v = max(samecol)
    else:
        _, k, v = max((max(m[3] for m in v), k, v) for k, v in exact2.items())
    member = max(v, key=lambda m: min(c for r, c in m[0]))
    out = [list(r) for r in grid]
    for r, c in member[0]:
        out[r][c] = L[1]
    return tuple(tuple(r) for r in out)

def predict(grid):
    return [list(r) for r in solve(tuple(map(tuple, grid)))]
'''
