    csL=set(Lobj[0]); Hg,Wg=len(gi),len(gi[0])
    Lr=[r for r,c in csL]; Lc=[c for r,c in csL]; Lmid=(sum(Lr)/len(Lr),sum(Lc)/len(Lc))
