            'sz':sz,'col':c,'dcx':abs(sum(rs)/len(rs)-Lmid[0]),'dcy':abs(sum(cll)/len(cll)-Lmid[1])}
    return objs,Lobj,fts
def pairs_of(gi,diag=True):
